DO $$
DECLARE v_page jsonb;
BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0560000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 56, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "56", "printedPageNumber": 56, "pdfPageNumber": 439, "sequenceIndex": 46, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0560100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0560000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "saying, \"A person who in all sincerity is constant in his salaat with Jamaat for forty days, without missing the first takbeer, receives two awards: one for deliverance from Hell and the other for freedom from nifaaq.\"\n\nIf a person is regular in his salaat (with sincerity) for forty days and joins the Jamaat from the very start (i.e., when the Imaam calls out his first takbeer), then he shall neither be a munaafiq nor shall he go to Hell. A munaafiq is a person who feigns being a Muslim, but there is kufr in his heart. Genesis of man (according to hadith) takes place in periods of forty days. This seems to be the significance of forty days in this hadith, and so the Soofis attach importance to this period (called Chillah in Urdu) for purposes of spiritual discipline.\n\nLucky indeed are the persons who do not miss their first takbeer for years together.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560200-0000-4000-8000-000000000001", "structuralNodeId": "b0560100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560300-0000-4000-8000-000000000001", "structuralNodeId": "b0560100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ من توضأ فأحسن وضوءه ثم راح فوجد الناس قد صلوا أعطاه الله عز وجل مثل أجر من صلاها وحضرها لا ينقص ذلك من أجورهم شيئاً رواه أبو داود والنسائي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560400-0000-4000-8000-000000000001", "structuralNodeId": "b0560100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"A person who performs wudhu scrupulously, and then goes to the musjid and finds that Jamaat is over, receives a reward equal to that of Jamaat. This would not diminish anything from the reward of those who have actually performed their salaat with Jamaat.\"\n\nThis is indeed Allah''s great favour and beneficence that the mere effort and a slight exertion is enough to entitle us to a reward of Jamaat, though actually we fail to join it. Who is the loser then if we ourselves get left, and miss the bounties of the most Bountiful?\n\nThis hadith also shows that we should not postpone going to the musjid in apprehension of the Jamaat being over. Even if we find on reaching the musjid that Jamaat is over, we will still get the reward thereof. If, however, we are certain that the Jamaat is already over, then there is of course no idea in going to the musjid for Jamaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0570000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 57, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "57", "printedPageNumber": 57, "pdfPageNumber": 440, "sequenceIndex": 47, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0570100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0570200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0570000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570100-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570200-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن قباث بن أشيم الليثي رضي الله عنه قال قال رسول الله ﷺ صلاة الرجلين يؤم أحدهما صاحبه أزكى عند الله من صلاة أربعة تترى وصلاة أربعة أزكى عند الله من صلاة ثمانية تترى وصلاة ثمانية يؤمهم أحدهم أزكى عند الله من صلاة مائة تترى رواه البزار والطبراني", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570300-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Qubaath bin Ashyam Allaithi (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Two persons performing salaat together with one as Imaam are liked by Allah more than four persons saying salaat individually. Similarly four persons performing salaat with Jamaat are liked by Allah more than eight persons saying it individually. Similarly again, eight persons performing salaat with Jamaat are liked by Allah more than one hundred persons saying it individually.\"\n\nIn another hadith it is said, \"A big Jamaat is more preferred by Allah than a small Jamaat.\" Some people think that there is no harm in having a small Jamaat of their own at their houses or at their business premises. This is not correct, as in the first place they are deprived of the reward of saying salaat in the musjid and secondly, they lose the blessing of salaat with a big Jamaat. The bigger the congregation, the more pleasing it is to Allah. When our sole aim is to achieve the pleasure of Allah, why should we not adopt a manner more pleasing to Him. It is reported in a hadith that Allah is pleased to see three things, namely, a row of worshippers offering salaat with Jamaat, a person busy in salaat at the time of Tahajjud at the dead of night, and a person fighting in the way of Allah.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570400-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570500-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن سهل بن سعد الساعدي رضي الله عنه قال قال رسول الله ﷺ بشر المشائين في الظلم إلى المساجد بالنور التام يوم القيامة رواه ابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570600-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Sahl bin Sa''d (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Give glad tidings to those who go to the musjid frequently during hours of darkness, for they will have perfect light on the Day of Judgement.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0580000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 58, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "58", "printedPageNumber": 58, "pdfPageNumber": 441, "sequenceIndex": 48, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0580000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The value of going to the musjid in the darkness of night shall be realised on the dreadful Day of Judgement, when everybody shall be in a very miserable plight. A person subjecting himself to inconvenience in the hours of darkness in this world shall be more than compensated in the next, as he shall carry with him a light more glorious than that of the sun. In a hadith it is reported that such persons shall occupy the pulpits of light, with no worry at all, while others will be in utter bewilderment. In another hadith it is said, \"Allah will say on the Day of Judgement, Where are My neighbours?\" The Angels will inquire, \"Who are Thy neighbours, O Allah?\" Allah will reply, \"Those who used to frequent the mosques.\"\n\nIn a hadith it is said, \"Of all the places on this Earth, the mosques are the dearest to Allah, and the markets are the most offensive to Him.\"\n\nIn another hadith, the ''masaajid'' are called \"The gardens of Paradise.\"\n\nHadhrat Abu Sa''eed (Radhiyallaho anho) narrates, \"The Prophet (Sallallaho alaihe wasallam) once said, ''Bear testimony to the Imaan of the person frequenting the musjid,'' and then he recited the following verse of the Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"He only shall tend Allah''s musjid who believes in Allah and the Last Day.\" (IV: 18).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The following are a few more ahaadith about the virtues of salaat with Jamaat:-\n\n1. \"Making wudhu when inconvenient, walking towards the musjid and sitting there (after one salaat), waiting for the next salaat, wipe out the sins.\"\n\n2. \"The farther a person lives from the ''musjid'' the greater the blessing he receives.\" This is so because a person coming from a distance shall have to walk more and, as already mentioned, every step will fetch him a blessing. For this very reason some companions have been reported to be taking short steps in going to the musjid in order to earn more blessings.\n\n3. \"There are three things in this world for which", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;